script:
(function () {
  'use strict';
  // 15 vs. 30-year mortgage: the same loan amount on two fixed-rate terms.
  //   Monthly payment M = P * i / (1 - (1 + i)^-n), i = annual rate / 12, n = years * 12 (M = P / n at 0%).
  //   Total interest = M * n - P. Balance after k payments B_k = P(1+i)^k - M((1+i)^k - 1) / i.
  //   Equity from payments after year y = P - B_(12y).
  // Checked in Node (scratchpad tests/w3b3_fth.test.js) against the closed form and an independent
  //   Python amortization: $300,000 at 6.5% for 30 years -> $1,896.20/mo, $382,633.47 total interest;
  //   $300,000 at 5.75% for 15 years -> $2,491.23/mo, $148,421.45 total interest; 0% rate -> P / n;
  //   balances reach $0.00 at the end of each term; blank or negative inputs show an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }
  function read(id) {
    var raw = String(el(id).value).trim();
    if (raw === '') return NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function payment(P, i, n) {
    if (P <= 0) return 0;
    if (i === 0) return P / n;
    return P * i / (1 - Math.pow(1 + i, -n));
  }

  function balanceAfter(P, i, n, M, k) {
    if (k >= n) return 0;
    if (i === 0) return Math.max(0, P - M * k);
    var g = Math.pow(1 + i, k);
    return Math.max(0, P * g - M * (g - 1) / i);
  }

  function loan(P, rate, years) {
    var i = rate / 100 / 12, n = years * 12, M = payment(P, i, n);
    return { P: P, i: i, n: n, years: years, rate: rate, M: M, total: M * n, interest: M * n - P };
  }

  function clearResults() {
    ['fthPayA', 'fthPayB', 'fthSaved', 'fthExtra', 'fthSummary'].forEach(function (id) { setText(id, '–'); });
    el('fthCompare').innerHTML = '';
    el('fthEquity').innerHTML = '';
  }

  function signed(x, f) { return (x < 0 ? '−' : '+') + (f || money).format(Math.abs(x)); }
  function signedNum(x, suffix) { return (x < 0 ? '−' : '+') + String(Math.abs(Math.round(x * 1000) / 1000)) + (suffix || ''); }

  function update() {
    var P = read('fthLoan'), rA = read('fthRateA'), rB = read('fthRateB'),
        tA = parseInt(el('fthTermA').value, 10), tB = parseInt(el('fthTermB').value, 10);
    var error = el('fthError'), msg = '';
    if (isNaN(P) || P <= 0) msg = 'Enter a loan amount greater than $0.';
    else if (isNaN(rA) || isNaN(rB) || rA < 0 || rB < 0 || rA > 30 || rB > 30) msg = 'Enter interest rates from 0% to 30%.';
    else if (!(tA > 0) || !(tB > 0)) msg = 'Choose a term for each loan.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    // Keep "A" as the shorter term so the labels always read correctly.
    var a = loan(P, rA, tA), b = loan(P, rB, tB);
    if (b.years < a.years) { var t = a; a = b; b = t; }
    var labA = a.years + '-year', labB = b.years + '-year';
    setText('fthPayALabel', labA + ' payment');
    setText('fthPayBLabel', labB + ' payment');
    setText('fthColA', labA);
    setText('fthColB', labB);
    setText('fthPayA', money.format(a.M));
    setText('fthPayB', money.format(b.M));
    var saved = b.interest - a.interest, extra = a.M - b.M;
    setText('fthSaved', money0.format(saved));
    setText('fthExtra', money.format(extra));

    var s;
    if (a.years === b.years) {
      s = Math.abs(saved) < 0.005 ? 'Both loans have the same term and rate, so they cost the same.' :
        'Both loans have the same term, so only the rate differs. The lower rate saves ' + money0.format(Math.abs(saved)) + ' in interest.';
    } else {
      s = 'The ' + labA + ' loan costs ' + money.format(Math.abs(extra)) + (extra >= 0 ? ' more' : ' less') + ' a month and ' +
          (saved >= 0 ? 'saves ' + money0.format(saved) : 'costs ' + money0.format(-saved) + ' more') + ' in interest. It is paid off ' +
          (b.years - a.years) + ' years sooner.';
    }
    setText('fthSummary', s);

    var rows = [
      ['Interest rate', a.rate + '%', b.rate + '%', signedNum(a.rate - b.rate, ' pts')],
      ['Monthly payment', money.format(a.M), money.format(b.M), signed(a.M - b.M)],
      ['Number of payments', String(a.n), String(b.n), signedNum(a.n - b.n)],
      ['Total of payments', money0.format(a.total), money0.format(b.total), signed(a.total - b.total, money0)],
      ['Total interest', money0.format(a.interest), money0.format(b.interest), signed(a.interest - b.interest, money0)],
      ['Interest per $1 borrowed', money.format(a.interest / P), money.format(b.interest / P), signed((a.interest - b.interest) / P)]
    ];
    el('fthCompare').innerHTML = rows.map(function (r) {
      return '<tr><th scope="row">' + r[0] + '</th><td>' + r[1] + '</td><td>' + r[2] + '</td><td>' + r[3] + '</td></tr>';
    }).join('');

    var out = [];
    for (var y = 1; y <= b.years; y++) {
      var ba = balanceAfter(P, a.i, a.n, a.M, y * 12), bb = balanceAfter(P, b.i, b.n, b.M, y * 12);
      out.push('<tr><td>' + y + '</td><td>' + money0.format(ba) + '</td><td>' + money0.format(P - ba) + ' (' + Math.round((P - ba) / P * 100) +
        '%)</td><td>' + money0.format(bb) + '</td><td>' + money0.format(P - bb) + ' (' + Math.round((P - bb) / P * 100) +
        '%)</td><td>' + money0.format(bb - ba) + '</td></tr>');
    }
    el('fthEquity').innerHTML = out.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('fthForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
